script.setup:
// circlify packed the Python standard library (folders → modules, sized by lines of code)
// into nested circles (recipe circlify.stdlib-packing → circles.json). Hover to read a
// circle, click a folder to zoom in, click outside it to zoom back out.
const data = await (await fetch(ctx.assets["circles.json"])).json();
const gl = ctx.gl;
const circles = data.circles.slice().sort((a, b) => a.level - b.level || b.r - a.r);
const tops = [...new Set(circles.filter((c) => c.level === 1 && !c.leaf).sort((a, b) => b.r - a.r).map((c) => c.path))];
const hsl = (h, s, l) => { const k = (n) => (n + h * 12) % 12, a = s * Math.min(l, 1 - l); return [0, 8, 4].map((n) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1))); };
const inst = new Float32Array(circles.length * 8);
circles.forEach((c, i) => {
  const top = tops.indexOf(c.path.split("/")[0]);
  const jitter = [...c.path].reduce((a, ch) => (a * 31 + ch.charCodeAt(0)) % 997, 7) / 997;
  const col = top < 0 ? hsl(0.55 + jitter * 0.12, 0.2, 0.42 + jitter * 0.16) : hsl((top * 0.618 + 0.05) % 1, 0.62, 0.6);
  inst.set([c.x, c.y, c.r, c.level, ...col, c.leaf ? 1 : 0], i * 8);
});
const vao = gl.createVertexArray();
gl.bindVertexArray(vao);
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, inst, gl.STATIC_DRAW);
for (const [loc, size, off] of [[1, 4, 0], [2, 3, 4], [3, 1, 7]]) {
  gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 32, off * 4); gl.vertexAttribDivisor(loc, 1);
}
gl.bindVertexArray(null);
const vs = `#version 300 es
layout(location=0) in vec2 a_corner; layout(location=1) in vec4 a_circle; layout(location=2) in vec3 a_color; layout(location=3) in float a_leaf;
uniform vec3 u_view; uniform vec2 u_resolution; uniform float u_gap;
out vec2 v_q; out vec3 v_color; out float v_leaf; out float v_px; out float v_id; out float v_level;
void main(){
  float r = a_circle.z * (1.0 - u_gap);
  vec2 p = a_circle.xy + a_corner * r * 1.04;
  float m = min(u_resolution.x, u_resolution.y);
  vec2 ndc = (p - u_view.xy) / u_view.z * m / u_resolution;
  v_q = a_corner * 1.04; v_color = a_color; v_leaf = a_leaf; v_px = r / u_view.z * m * 0.5; v_id = float(gl_InstanceID); v_level = a_circle.w;
  gl_Position = vec4(ndc, 0.0, 1.0);
}`;
const fs = `#version 300 es
precision highp float;
in vec2 v_q; in vec3 v_color; in float v_leaf; in float v_px; in float v_id; in float v_level; out vec4 outColor;
uniform float u_hover; uniform float u_time; uniform float u_glow;
void main(){
  float d = length(v_q) - 1.0;
  float aa = 1.5 / max(v_px, 1.0);
  float inside = 1.0 - smoothstep(-aa, aa, d);
  if (inside <= 0.0) discard;
  bool hot = abs(v_id - u_hover) < 0.5;
  vec3 c; float a;
  if (v_leaf > 0.5) {
    float shade = 0.75 + 0.35 * (1.0 - dot(v_q, v_q)) + 0.12 * v_q.y;
    c = v_color * shade; a = 0.95;
    float edge = 1.0 - smoothstep(0.0, aa * 2.0, abs(d + aa * 1.5));
    c = mix(c, vec3(1.0), edge * 0.25);
  } else {
    float ring = 1.0 - smoothstep(0.0, aa * 1.6, abs(d + aa));
    c = v_color * (0.16 + 0.05 * v_level) + v_color * ring * 0.9; a = 0.55 + ring * 0.45;
  }
  if (hot) { float pulse = 0.5 + 0.5 * sin(u_time * 6.0); c = mix(c, vec3(1.0), 0.35 + 0.15 * pulse); a = max(a, 0.9); }
  c *= u_glow;
  outColor = vec4(c * a * inside, a * inside);
}`;
const labels = new OffscreenCanvas(1, 1);
Object.assign(ctx.state, {
  data, circles, vao, labels, l2d: labels.getContext("2d"), labelTex: gl.createTexture(), labelKey: "",
  view: [0, 0, 1.05], target: [0, 0, 1.05], focus: null, hover: -1,
  p: ctx.utils.createProgram(vs, fs),
  overlay: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_labels;
void main(){ outColor = texture(u_labels, vec2(v_uv.x, 1.0 - v_uv.y)); }`),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
void main(){ vec2 q = v_uv - 0.5; outColor = vec4(mix(vec3(0.05, 0.055, 0.075), vec3(0.02, 0.022, 0.03), length(q) * 1.4), 1.0); }`),
});
ctx.publish("modules", circles.filter((c) => c.leaf).length);
ctx.publish("total lines", data.total_lines);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution, m = Math.min(w, h);
// Screen ↔ packing coordinates (the packing lives in the unit circle).
const toWorld = (mx, my) => [s.view[0] + (mx * w - w / 2) / (m / 2) * s.view[2], s.view[1] + (h / 2 - my * h) / (m / 2) * s.view[2]];
const [wx, wy] = toWorld(ctx.mouse[0], ctx.mouse[1]);
const hit = (pred) => { let best = -1; s.circles.forEach((c, i) => { if (pred(c) && (wx - c.x) ** 2 + (wy - c.y) ** 2 < c.r * c.r) best = i; }); return best; };
// No hover until the pointer has moved (the default mouse sits mid-canvas).
s.moved ||= ctx.mouse[0] !== ctx.mousePrev[0] || ctx.mouse[1] !== ctx.mousePrev[1] || ctx.mouseDown;
s.hover = s.moved ? hit(() => true) : -1;
if (ctx.mouseDown && !s.wasDown) {
  const folder = hit((c) => !c.leaf && c !== s.focus);
  const inFocus = s.focus && (wx - s.focus.x) ** 2 + (wy - s.focus.y) ** 2 < s.focus.r ** 2;
  if (folder >= 0 && (!s.focus || s.circles[folder].path.startsWith(s.focus.path + "/"))) s.focus = s.circles[folder];
  else if (!inFocus) s.focus = s.focus && s.focus.level > 1 ? s.circles.find((c) => c.path === s.focus.path.split("/").slice(0, -1).join("/")) ?? null : null;
  s.target = s.focus ? [s.focus.x, s.focus.y, s.focus.r * 1.08] : [0, 0, 1.05];
}
s.wasDown = ctx.mouseDown;
const k = 1 - Math.exp(-ctx.dt * 6);
for (let i = 0; i < 2; i++) s.view[i] += (s.target[i] - s.view[i]) * k;
s.view[2] = Math.exp(Math.log(s.view[2]) + (Math.log(s.target[2]) - Math.log(s.view[2])) * k);
// A slow drift keeps the overview alive when nothing is focused.
const view = [s.view[0] + Math.sin(ctx.time * 0.3) * 0.01 * s.view[2], s.view[1] + Math.cos(ctx.time * 0.23) * 0.01 * s.view[2], s.view[2]];
const hov = s.circles[s.hover];
ctx.publish("hover", hov ? `${hov.path} — ${hov.lines.toLocaleString()} lines` : "");

ctx.utils.drawFullscreen(s.bg);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
gl.useProgram(s.p);
ctx.utils.setStandardUniforms(s.p);
ctx.utils.setUniforms(s.p, { u_view: view, u_hover: s.hover });
gl.bindVertexArray(s.vao);
gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, s.circles.length);
gl.bindVertexArray(null);

// Labels: drawn with canvas 2D only when the view or hover changes, then blended on top.
const key = view.map((v) => v.toFixed(4)).join() + s.hover + w + "x" + h;
if (key !== s.labelKey) {
  s.labelKey = key;
  const L = s.l2d;
  if (s.labels.width !== w || s.labels.height !== h) { s.labels.width = w; s.labels.height = h; }
  L.clearRect(0, 0, w, h);
  L.textAlign = "center"; L.textBaseline = "middle";
  const px = (c) => [w / 2 + (c.x - view[0]) / view[2] * m / 2, h / 2 - (c.y - view[1]) / view[2] * m / 2, c.r / view[2] * m / 2];
  for (const c of s.circles) {
    const [x, y, r] = px(c);
    if (r < 22 || x + r < 0 || x - r > w || y + r < 0 || y - r > h) continue;
    const isFolder = !c.leaf;
    if (isFolder && r > w * 0.6) continue;
    const size = Math.max(9, Math.min(r * (isFolder ? 0.2 : 0.3), 26)) * (w / 900 + 0.4);
    const name = c.name.replace(/\.py$/, "");
    L.font = `${isFolder ? 600 : 400} ${size}px ui-sans-serif, system-ui, sans-serif`;
    if (L.measureText(name).width > r * 1.9) continue;
    L.fillStyle = isFolder ? "rgba(255,255,255,0.92)" : "rgba(10,12,18,0.82)";
    L.fillText(name, x, isFolder ? y - r + size * 1.1 : y);
  }
  if (hov) {
    const [x, y, r] = px(hov);
    const text = `${hov.path}  ·  ${hov.lines.toLocaleString()} lines`;
    const size = 12 * (w / 900 + 0.5);
    L.font = `500 ${size}px ui-sans-serif, system-ui, sans-serif`;
    const tw = L.measureText(text).width + size * 1.2;
    const tx = Math.min(Math.max(x, tw / 2 + 4), w - tw / 2 - 4), ty = Math.max(y - r - size * 1.2, size * 1.2);
    L.fillStyle = "rgba(8,9,14,0.85)"; L.beginPath(); L.roundRect(tx - tw / 2, ty - size * 0.95, tw, size * 1.9, size * 0.5); L.fill();
    L.fillStyle = "white"; L.fillText(text, tx, ty);
  }
  gl.bindTexture(gl.TEXTURE_2D, s.labelTex);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.labels);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
}
gl.useProgram(s.overlay);
ctx.utils.bindTexture(s.overlay, "u_labels", s.labelTex, 0);
ctx.utils.drawFullscreen(s.overlay);
gl.disable(gl.BLEND);
